using Cntryl.Portia;

namespace Bdgrz.Compliance.Hosting.Persistence;

/// <summary>Preflights every attributed envelope before the inner store can open an append session.</summary>
sealed class PersistenceEventStore(IEventStore inner, IDomainEventSerializer serializer)
    : IEventStore, IDomainEventNotifier
{
    public ValueTask AppendAsync(EventStreamAddress stream, ulong expectedStreamPosition,
        IReadOnlyList<DomainEvent> events, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(stream);
        ArgumentNullException.ThrowIfNull(events);
        ct.ThrowIfCancellationRequested();
        foreach (var ev in events)
        {
            ct.ThrowIfCancellationRequested();
            FitzFrameLimits.CheckEvent(stream, serializer.Serialize(ev).Length);
        }
        return inner.AppendAsync(stream, expectedStreamPosition, events, ct);
    }

    public IAsyncEnumerable<DomainEventRecord> ReadAsync(EventStreamAddress stream, ulong fromOffset,
        CancellationToken ct) => inner.ReadAsync(stream, fromOffset, ct);

    public IAsyncEnumerable<DomainEventRecord> ReadAsync(EventStreamPattern pattern, EventCursor cursor,
        CancellationToken ct) => inner.ReadAsync(pattern, cursor, ct);

    public ValueTask<IDomainEventSubscription> SubscribeAsync(EventStreamPattern pattern,
        CancellationToken ct = default) => inner is IDomainEventNotifier notifier
        ? notifier.SubscribeAsync(pattern, ct)
        : throw new NotSupportedException("The underlying event store does not support notifications.");
}

using System.Security.Claims;
using Cntryl.Portia;

namespace Bdgrz.Compliance.Hosting.Persistence;

/// <summary>Returns expected pre-append size rejection through the shared transport-independent result.</summary>
sealed class PersistenceValidationRequestBus(IRequestBus inner) : IRequestBus
{
    public RequestDispatchContext CreateContext(ClaimsPrincipal actor, RequestMetadata? metadata = null) =>
        inner.CreateContext(actor, metadata);

    public ValueTask<Result> AuthorizeAsync(IRequestBase request, RequestDispatchContext context,
        CancellationToken ct = default) => inner.AuthorizeAsync(request, context, ct);

    public async ValueTask<Result> DispatchAsync(IRequest request, RequestDispatchContext context,
        CancellationToken ct = default)
    {
        try
        {
            return await inner.DispatchAsync(request, context, ct).ConfigureAwait(false);
        }
        catch (EventFrameSizeException ex)
        {
            return Result.Failure(new RequestError(RequestErrorKind.Validation, ex.Message));
        }
    }

    public async ValueTask<Result<TOut>> DispatchAsync<TOut>(IRequest<TOut> request,
        RequestDispatchContext context, CancellationToken ct = default)
    {
        try
        {
            return await inner.DispatchAsync(request, context, ct).ConfigureAwait(false);
        }
        catch (EventFrameSizeException ex)
        {
            return Result<TOut>.Failure(new RequestError(RequestErrorKind.Validation, ex.Message));
        }
    }

    public IAsyncEnumerable<TOut> DispatchStreamAsync<TOut>(IStreamRequest<TOut> request,
        RequestDispatchContext context, CancellationToken ct = default) =>
        inner.DispatchStreamAsync(request, context, ct);
}

using Cntryl.Fitz;
using Cntryl.Portia;
using Microsoft.Extensions.DependencyInjection;

namespace Bdgrz.Compliance.Hosting.Persistence;

static class PersistenceServiceCollectionExtensions
{
    public static void AddPersistenceSafety(this IServiceCollection services)
    {
        Decorate<IEventStore>(services, (provider, inner) =>
            new PersistenceEventStore(inner, provider.GetRequiredService<IDomainEventSerializer>()));
        Decorate<IKvClient>(services, (_, inner) => new PersistenceKvClient(inner));
        Decorate<IRequestBus>(services, (_, inner) => new PersistenceValidationRequestBus(inner));
    }

    // Keep the original registration keyed so DI still owns its lifetime/disposal, including custom stores.
    static void Decorate<T>(IServiceCollection services, Func<IServiceProvider, T, T> wrap) where T : class
    {
        var original = services.Last(descriptor => !descriptor.IsKeyedService && descriptor.ServiceType == typeof(T));
        var key = new object();
        services.Remove(original);
        if (original.ImplementationInstance is { } instance)
            services.Add(ServiceDescriptor.KeyedSingleton(typeof(T), key, instance));
        else if (original.ImplementationFactory is { } factory)
            services.Add(ServiceDescriptor.DescribeKeyed(typeof(T), key, (provider, _) => factory(provider), original.Lifetime));
        else
            services.Add(ServiceDescriptor.DescribeKeyed(typeof(T), key,
                original.ImplementationType ?? throw new InvalidOperationException("A persistence service requires an implementation."),
                original.Lifetime));
        services.Add(ServiceDescriptor.Describe(typeof(T),
            provider => wrap(provider, provider.GetRequiredKeyedService<T>(key)), original.Lifetime));
    }
}

using Cntryl.Fitz;

namespace Bdgrz.Compliance.Hosting.Persistence;

/// <summary>Checks the actual KV operation, including its route and key, before forwarding it.</summary>
sealed class PersistenceKvClient(IKvClient inner) : IKvClient
{
    public async Task<IKvTransaction> BeginAsync(string route, KvMode mode = KvMode.ReadWrite,
        CancellationToken ct = default)
    {
        ct.ThrowIfCancellationRequested();
        FitzFrameLimits.CheckKv(route, 5); // Route length prefix and transaction mode.
        return new Transaction(await inner.BeginAsync(route, mode, ct).ConfigureAwait(false));
    }

    public Task<KvSubscription> SubscribeAsync(string pattern, CancellationToken ct = default) =>
        inner.SubscribeAsync(pattern, ct);

    sealed class Transaction(IKvTransaction inner) : IKvTransaction
    {
        public bool SupportsExclusiveScan => inner.SupportsExclusiveScan;
        public string Route => inner.Route;

        public Task<KvGetResult> GetAsync(ReadOnlyMemory<byte> key, CancellationToken ct = default)
        {
            Check(16L + key.Length, ct);
            return inner.GetAsync(key, ct);
        }

        public Task PutAsync(ReadOnlyMemory<byte> key, ReadOnlyMemory<byte> value, CancellationToken ct = default)
        {
            Check(20L + key.Length + value.Length, ct);
            return inner.PutAsync(key, value, ct);
        }

        public Task InsertAsync(ReadOnlyMemory<byte> key, ReadOnlyMemory<byte> value, CancellationToken ct = default)
        {
            Check(20L + key.Length + value.Length, ct);
            return inner.InsertAsync(key, value, ct);
        }

        public Task DeleteAsync(ReadOnlyMemory<byte> key, CancellationToken ct = default)
        {
            Check(16L + key.Length, ct);
            return inner.DeleteAsync(key, ct);
        }

        public Task DeleteRangeAsync(ReadOnlyMemory<byte> startKey, ReadOnlyMemory<byte> endKey,
            CancellationToken ct = default)
        {
            Check(20L + startKey.Length + endKey.Length, ct);
            return inner.DeleteRangeAsync(startKey, endKey, ct);
        }

        public Task<KvScanResult> ScanAsync(KvScanQuery query, CancellationToken ct = default)
        {
            ArgumentNullException.ThrowIfNull(query);
            var size = 16L + (query.StartKey is { } start ? 4L + start.Length : 0) +
                (query.EndKey is { } end ? 4L + end.Length : 0) +
                (query.Limit.HasValue ? 4 : 0) + (query.StartExclusive ? 1 : 0);
            Check(size, ct);
            return inner.ScanAsync(query, ct);
        }

        public Task CommitAsync(KvDurability durability, CancellationToken ct = default)
        {
            Check(13, ct);
            return inner.CommitAsync(durability, ct);
        }

        public Task RollbackAsync(CancellationToken ct = default)
        {
            Check(12, ct);
            return inner.RollbackAsync(ct);
        }

        public ValueTask DisposeAsync() => inner.DisposeAsync();

        void Check(long size, CancellationToken ct)
        {
            ct.ThrowIfCancellationRequested();
            FitzFrameLimits.CheckKv(Route, size);
        }
    }
}

using System.Text;
using Cntryl.Portia;

namespace Bdgrz.Compliance.Hosting.Persistence;

static class FitzFrameLimits
{
    // Fitz.Core 2.0.0: StreamSession and KvTransaction encode operation payloads before FrameCodec.
    public static void CheckEvent(EventStreamAddress stream, int envelopeBytes)
    {
        var size = (long)envelopeBytes + Encoding.UTF8.GetByteCount(stream.ToString()) + 26;
        if (size > ushort.MaxValue)
            throw new EventFrameSizeException(size);
    }

    public static void CheckKv(string route, long operationBytesWithoutRoute)
    {
        var size = operationBytesWithoutRoute + Encoding.UTF8.GetByteCount(route);
        if (size > ushort.MaxValue)
            throw new KvFrameSizeException(size);
    }
}
